29	// blockingCompute 占用计算位置，直到 Close 置位取消标记后返回失败；
30	// started 在首次进入计算时关闭，用于确认作业已在运行。
31	func blockingCompute(started chan<- struct{}) func(uint64, []int64, int64, func() bool) (int64, int64, string, bool) {
32		var once sync.Once
33		return func(_ uint64, _ []int64, _ int64, canceled func() bool) (int64, int64, string, bool) {
34			once.Do(func() { close(started) })
35			for !canceled() {
36				time.Sleep(time.Millisecond)
37			}
38			return 0, 0, "aborted", false
39		}
