11	// assertDependencyInputsFailure 重开归档后作业必须呈现为依赖输入对应失败：
12	// 状态失败、查询与列举不再返回成功归档与实际输入，原作业号、提交人、
13	// 请求号、原始序列、种子与依赖顺序保留，失败原因指出无法对应或无法
14	// 使用的直接上游作业号并说明成功结果不可用，落盘记录同样已改写为失败。
15	// wantBlocker 为必须保留的阻断根因作业号：因直接上游结果失效时沿链条
16	// 保留最初根因；仅本作业保存的追加输入不符（上游全部有效）时必须为 0。
17	func assertDependencyInputsFailure(t *testing.T, s *Store, j *Job, wantDep uint64, keyword string, wantBlocker uint64) {
18		t.Helper()
19		g, err := s.Get(j.ID)
20		if err != nil {
21			t.Fatal(err)
22		}
23		if g.Status != StatusFailed {
24			t.Fatalf("job %d must fail closed, got %s", j.ID, g.Status)
25		}
26		if g.BlockerID != wantBlocker {
27			t.Fatalf("job %d blocker=%d want root %d (reason=%q)", j.ID, g.BlockerID, wantBlocker, g.FailureReason)
28		}
29		if g.Archive != nil || g.EffectiveValues != nil {
30			t.Fatalf("job %d must not carry archive/effective inputs: archive=%v effective=%v",
31				j.ID, g.Archive, g.EffectiveValues)
32		}
33		if g.ID != j.ID || g.Submitter != j.Submitter || g.RequestID != j.RequestID || g.Seed != j.Seed {
34			t.Fatalf("identity changed: got id=%d submitter=%q request=%q seed=%d",
35				g.ID, g.Submitter, g.RequestID, g.Seed)
36		}
37		if len(g.Values) != len(j.Values) {
38			t.Fatalf("original values changed: %v, want %v", g.Values, j.Values)
39		}
40		for i := range j.Values {
41			if g.Values[i] != j.Values[i] {
42				t.Fatalf("original values changed: %v, want %v", g.Values, j.Values)
43			}
44		}
45		if len(g.Dependencies) != len(j.Dependencies) {
46			t.Fatalf("dependency order changed: %v, want %v", g.Dependencies, j.Dependencies)
47		}
48		for i := range j.Dependencies {
49			if g.Dependencies[i] != j.Dependencies[i] {
50				t.Fatalf("dependency order changed: %v, want %v", g.Dependencies, j.Dependencies)
51			}
52		}
53		if !strings.Contains(g.FailureReason, "作业 "+itoa(wantDep)) ||
54			!strings.Contains(g.FailureReason, keyword) ||
55			!strings.Contains(g.FailureReason, "成功结果不可用") {
56			t.Fatalf("job %d reason=%q must name upstream %d with %q and state success results unusable",
57				j.ID, g.FailureReason, wantDep, keyword)
58		}
59		// 按提交人列举时同样不返回成功归档与实际输入。
60		listed, err := s.List(j.Submitter, time.Time{}, time.Time{})
61		if err != nil {
62			t.Fatal(err)
63		}
64		found := false
65		for _, lj := range listed {
66			if lj.ID == j.ID {
67				found = true
68				if lj.Status != StatusFailed || lj.Archive != nil || lj.EffectiveValues != nil {
69					t.Fatalf("listed job %d must be failed without archive: %s", j.ID, lj.Status)
70				}
71			}
72		}
73		if !found {
74			t.Fatalf("job %d missing from submitter listing", j.ID)
75		}
76		// 落盘记录同样已改写为失败。
77		data, err := os.ReadFile(filepath.Join(s.Dir(), jobFileName(j.ID)))
78		if err != nil {
79			t.Fatal(err)
80		}
81		if !strings.Contains(string(data), `"status": "failed"`) {
82			t.Fatal("on-disk record must be rewritten as failed")
83		}
84	}
85	
86	// 原始序列 [10]，两个上游总和分别为 3 和 -2，依赖列表先引用总和为 -2 的
87	// 作业：正确的实际输入是 [10,-2,3]。记录写成 [10,3,-2] 时总和仍为 11、
88	// 平方和仍为 113，摘要、日志与校验值也都与这份错误输入自洽，重开后仍
89	// 必须判定该成功结果不可用；上游自身通过校验，不受下游错误影响。
90	func TestReopenRejectsSwappedDependencySums(t *testing.T) {
91		dir := t.TempDir()
92		s, err := Open(dir)
93		if err != nil {
94			t.Fatal(err)
95		}
96		u1 := mustSubmit(t, s, SubmitRequest{Submitter: "a", RequestID: "u1", Values: []int64{1, 2}})  // 和 3
97		u2 := mustSubmit(t, s, SubmitRequest{Submitter: "a", RequestID: "u2", Values: []int64{1, -3}}) // 和 -2
98		waitStatus(t, s, u1.ID, StatusSucceeded)
99		waitStatus(t, s, u2.ID, StatusSucceeded)
100		down := mustSubmit(t, s, SubmitRequest{
101			Submitter: "a", RequestID: "down", Values: []int64{10}, Seed: 9,
102			Dependencies: []uint64{u2.ID, u1.ID}, // 先引用总和为 -2 的作业
103		})
104		done := waitStatus(t, s, down.ID, StatusSucceeded)
105		if done.Archive.Sum != 11 || done.Archive.SumOfSquares != 113 {
106			t.Fatalf("real result=%d,%d", done.Archive.Sum, done.Archive.SumOfSquares)
107		}
108		before, _ := s.Get(down.ID)
109		if err := s.Close(); err != nil {
110			t.Fatal(err)
111		}
112	
113		// 追加部分次序调换：[10,3,-2] 与 [10,-2,3] 的总和、平方和完全相同。
114		rewriteRecordEffectiveInputs(t, dir, down.ID, []int64{10, 3, -2})
115	
116		s2, err := Open(dir)
117		if err != nil {
118			t.Fatal(err)
119		}
120		defer s2.Close()
121		// 第一个对不上的位置对应依赖列表中的 u2。
122		assertDependencyInputsFailure(t, s2, before, u2.ID, "无法对应", 0)
123	
124		// 上游自身通过校验，不因下游追加值错误而改动。
125		for _, id := range []uint64{u1.ID, u2.ID} {
126			g, err := s2.Get(id)
127			if err != nil {
128				t.Fatal(err)
129			}
130			if g.Status != StatusSucceeded || g.Archive == nil {
131				t.Fatalf("upstream %d must stay succeeded: %s", id, g.Status)
132			}
133		}
134		// 无关作业继续正常查询和计算。
135		next := mustSubmit(t, s2, SubmitRequest{Submitter: "b", Values: []int64{1, 2, 3}})
136		nd := waitStatus(t, s2, next.ID, StatusSucceeded)
137		if nd.Archive.Sum != 6 || nd.Archive.SumOfSquares != 14 {
138			t.Fatalf("unrelated job result=%d,%d", nd.Archive.Sum, nd.Archive.SumOfSquares)
139		}
140	}
141	
142	// 负数、零以及不同上游恰好同和都按位置判断：正确的记录（含同和上游、
143	// 零和、负和）重开后保持原结果、摘要与校验值；追加值与对应位置上游
144	// 总和不符的记录失败。
145	func TestReopenDependencyAppendedInputsByPosition(t *testing.T) {
146		dir := t.TempDir()
147		s, err := Open(dir)
148		if err != nil {
149			t.Fatal(err)
150		}
151		u1 := mustSubmit(t, s, SubmitRequest{Submitter: "a", RequestID: "u1", Values: []int64{1, 2}})   // 和 3
152		u2 := mustSubmit(t, s, SubmitRequest{Submitter: "a", RequestID: "u2", Values: []int64{4, -1}})  // 和 3（同和）
153		u3 := mustSubmit(t, s, SubmitRequest{Submitter: "a", RequestID: "u3", Values: []int64{0, 0}})   // 和 0
154		u4 := mustSubmit(t, s, SubmitRequest{Submitter: "a", RequestID: "u4", Values: []int64{-2, -3}}) // 和 -5
155		for _, id := range []uint64{u1.ID, u2.ID, u3.ID, u4.ID} {
156			waitStatus(t, s, id, StatusSucceeded)
157		}
158		down := mustSubmit(t, s, SubmitRequest{
159			Submitter: "a", RequestID: "down", Values: []int64{7},
160			Dependencies: []uint64{u2.ID, u1.ID, u3.ID, u4.ID},
161		})
162		done := waitStatus(t, s, down.ID, StatusSucceeded)
163		// 实际输入 [7,3,3,0,-5]：sum=8，sq=49+9+9+0+25=92。
164		wantEff := []int64{7, 3, 3, 0, -5}
165		for i := range wantEff {
166			if done.Archive.EffectiveValues[i] != wantEff[i] {
167				t.Fatalf("effective=%v want %v", done.Archive.EffectiveValues, wantEff)
168			}
169		}
170		if done.Archive.Sum != 8 || done.Archive.SumOfSquares != 92 {
171			t.Fatalf("result=%d,%d want 8,92", done.Archive.Sum, done.Archive.SumOfSquares)
172		}
173		wantChecksum := done.Archive.Checksum
174		before, _ := s.Get(down.ID)
175		if err := s.Close(); err != nil {
176			t.Fatal(err)
177		}
178	
179		// 篡改副本：把 u4 的追加位置写成 5 而非 -5（绝对值相同，符号不同）。
180		d := t.TempDir()
181		copyArchive(t, dir, d)
182		bad := append([]int64(nil), wantEff...)
183		bad[4] = 5
184		rewriteRecordEffectiveInputs(t, d, down.ID, bad)
185		sBad, err := Open(d)
186		if err != nil {
187			t.Fatal(err)
188		}
189		defer sBad.Close()
190		assertDependencyInputsFailure(t, sBad, before, u4.ID, "无法对应", 0)
191	
192		// 原始归档重开：同和上游、零和、负和都按位置对应，结果与校验值不变。
193		s2, err := Open(dir)
194		if err != nil {
195			t.Fatal(err)
196		}
197		defer s2.Close()
198		g, err := s2.Get(down.ID)
199		if err != nil {
200			t.Fatal(err)
201		}
202		if g.Status != StatusSucceeded || g.Archive == nil {
203			t.Fatalf("valid dependent archive must survive reopen: %s", g.Status)
204		}
205		if g.Archive.Sum != 8 || g.Archive.SumOfSquares != 92 || g.Archive.Checksum != wantChecksum {
206			t.Fatalf("archive changed across reopen: %+v", g.Archive)
207		}
208		for i := range wantEff {
209			if g.EffectiveValues[i] != wantEff[i] {
210				t.Fatalf("effective=%v want %v", g.EffectiveValues, wantEff)
211			}
212		}
213	}
214	
215	// 上游在本次打开中因已有校验被判失败时，已经归档成功的下游也不能继续使用
216	// 它：下游及其更下游的成功记录一并改判失败，失败原因指出无法使用的直接
217	// 上游作业号；仍在排队等待失效作业的下游沿用既有依赖失败处理。
218	func TestReopenInvalidatedUpstreamFailsSucceededDependents(t *testing.T) {
219		dir := t.TempDir()
220		s, err := Open(dir)
221		if err != nil {
222			t.Fatal(err)
223		}
224		up := mustSubmit(t, s, SubmitRequest{Submitter: "a", RequestID: "up", Values: []int64{2, -3}}) // 和 -1
225		waitStatus(t, s, up.ID, StatusSucceeded)
226		mid := mustSubmit(t, s, SubmitRequest{
227			Submitter: "a", RequestID: "mid", Values: []int64{5},
