264		assertDependencyInputsFailure(t, s2, downBefore, mid.ID, "无法使用", up.ID)
265		// 排队等待失效作业的下游按既有依赖失败处理：直接上游为 mid，根因沿
266		// 链条保留为最初校验失败的 up。
