308	// 旧格式单依赖记录（无 dependencies 字段）按同一含义核对追加值：
309	// 追加值不等于唯一上游总和时失败；正确记录保持原结果（既有测试覆盖）。
310	func TestReopenLegacySingleDependencyWrongAppendedSum(t *testing.T) {
311		dir := t.TempDir()
312		base := time.Date(2026, 3, 4, 5, 6, 7, 0, time.UTC)
313	
