		Submitter: "a", Values: []int64{3},
		HasDependency: true, DependencyID: mid.ID,
	})
	independent := mustSubmit(t, s, SubmitRequest{Submitter: "a", Values: []int64{9}})
	// 此时唯一位置被 id 1 占用，mid/far 等依赖、independent 等位置。

