	if got.Status != StatusSucceeded || got.Archive == nil {
		t.Fatal("succeeded result changed after rejected cancel")
	}
	// 已失败的作业同样不能取消，原因保持。
	if _, err := s.Cancel(mm.ID); !errors.Is(err, ErrNotCancellable) {
		t.Fatalf("cancel failed: %v", err)
	}

