// 再说明沿链条保留的根因作业号。
func restoredBlockedReason(dep *storedJob, depID, root uint64, detail string) string {
	reason := detail + "，阻断本作业继续计算"
	if dep != nil && dep.status == StatusFailed && dep.failureReason != "" {
		reason += "（其失败原因：" + dep.failureReason + "）"
	}
	if root != depID {
		reason += fmt.Sprintf("；阻断根因为作业 %d", root)
	}
	return reason
}

// archiveIntact 复算成功归档的全部确定性字段，任何不一致都视为不可用。
func archiveIntact(j *storedJob) bool {
	a := j.archive
	if a == nil {
		return false
	}
	// 归档中的原始参数必须与记录顶层字段一致。
	if a.JobID != j.id || a.Submitter != j.submitter || a.RequestID != j.requestID ||
		a.Seed != j.seed || a.HasDependency != (len(j.dependencies) > 0) {
		return false
	}
	if a.HasDependency && a.DependencyID != depID(j) {
		return false
	}
	// 依赖列表（内容与次序）必须一致。旧格式归档没有 dependencies 字段，
	// 由单依赖字段推导后再比较。
	aDeps := append([]uint64(nil), a.Dependencies...)

}

